create table if not exists public.follows (follower uuid not null default auth.uid() references auth.users(id) on delete cascade, followed uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (follower, followed), check (follower <> followed));
alter table public.follows enable row level security;
drop policy if exists "seguir: ler" on public.follows;
create policy "seguir: ler" on public.follows for select to authenticated using (true);
drop policy if exists "seguir: criar" on public.follows;
create policy "seguir: criar" on public.follows for insert to authenticated with check (follower = auth.uid());
drop policy if exists "seguir: remover" on public.follows;
create policy "seguir: remover" on public.follows for delete to authenticated using (follower = auth.uid());
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), author uuid not null default auth.uid() references auth.users(id) on delete cascade, recipient uuid not null references auth.users(id) on delete cascade, sender_name text not null default '', recipient_name text not null default '', text text not null check (char_length(text) between 1 and 500), created_at timestamptz not null default now(), read_at timestamptz, check (author <> recipient));
alter table public.messages enable row level security;
create index if not exists messages_rec_idx on public.messages (recipient, created_at desc);
create index if not exists messages_auth_idx on public.messages (author, created_at desc);
drop policy if exists "mensagens: ler" on public.messages;
create policy "mensagens: ler" on public.messages for select to authenticated using (author = auth.uid() or recipient = auth.uid());
drop policy if exists "mensagens: enviar" on public.messages;
create policy "mensagens: enviar" on public.messages for insert to authenticated with check (author = auth.uid());
drop policy if exists "mensagens: marcar lida" on public.messages;
create policy "mensagens: marcar lida" on public.messages for update to authenticated using (recipient = auth.uid()) with check (recipient = auth.uid());
revoke insert, update on public.messages from anon, authenticated;
grant insert (recipient, text) on public.messages to authenticated;
grant update (read_at) on public.messages to authenticated;
create or replace function public.dm_fill() returns trigger language plpgsql security definer set search_path = public as $$ declare rn text; begin select name into rn from profiles where id = new.recipient; if rn is null then raise exception 'Jogador não encontrado'; end if; new.recipient_name := rn; new.sender_name := coalesce((select name from profiles where id = new.author), 'Viajante'); return new; end $$;
drop trigger if exists dm_fill_t on public.messages;
create trigger dm_fill_t before insert on public.messages for each row execute function public.dm_fill();
drop trigger if exists bad_messages on public.messages;
create trigger bad_messages before insert on public.messages for each row execute function public.chk_bad('text');
drop trigger if exists rl_messages on public.messages;
create trigger rl_messages before insert on public.messages for each row execute function public.rate_limit('10','60');
